{
  "name": "auditor-mission-control",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "test": "vitest run",
    "typecheck": "tsc -b --noEmit",
    "lint": "oxlint",
    "preview": "vite preview"
  },
  "dependencies": {
    "framer-motion": "^12.43.0",
    "lightweight-charts": "^5.2.1",
    "react": "^19.3.0",
    "react-dom": "^19.3.0"
  },
  "devDependencies": {
    "@tailwindcss/vite": "^4.3.3",
    "@types/node": "^24.13.3",
    "@types/react": "^19.2.18",
    "@types/react-dom": "^19.2.7",
    "@vitejs/plugin-react": "^5.2.0",
    "oxlint": "^1.81.0",
    "tailwindcss": "^4.3.3",
    "typescript": "~5.9",
    "vite": "^7.3.7",
    "vitest": "^3.2.7"
  }
}
// Audit event contract, AUDITOR_SPEC.md section 16. One JSON object per line of events.jsonl.

export type Agent = "planner" | "researcher" | "mathematician" | "naysayer" | "reporter" | "triage";
export type Verdict = "kill" | "inconclusive" | "promising" | "cannot_audit";

export interface Stats {
  n: number;
  blocks: number;
  win_rate: number;
  mean: number;
  median: number;
  ci_low: number;
  ci_high: number;
  worst_trade: number;
  worst_window: number;
}
export type BaselineStats = Stats & { paired_ci_low: number };
export type EquityPoint = [string, number];

interface Base<T extends string, A extends Agent | null, P> {
  seq: number;
  ts: string;
  audit_id: string;
  type: T;
  agent: A;
  payload: P;
}

export type AuditStartedEvent = Base<"audit_started", null, { idea: string; trace_id: string | null; llm_budget: number; fault: string | null; provider?: string }>;
export type AgentStartedEvent = Base<"agent_started", Agent, { step: string }>;
export type AgentFinishedEvent = Base<"agent_finished", Agent, { step: string; status: "ok" | "error"; duration_ms: number; summary: unknown }>;
export type LlmCallEvent = Base<"llm_call", Agent, { model: string; prompt_tokens: number; completion_tokens: number; cost_usd: number; latency_ms: number }>;
export type ToolCalledEvent = Base<"tool_called", Agent, { tool: string; args: unknown }>;
export type ToolResultEvent = Base<"tool_result", Agent, { tool: string; ok: boolean; duration_ms: number; summary: string }>;
export type DataProgressEvent = Base<"data_progress", "researcher", { what: string; percent: number }>;
export type BacktestResultEvent = Base<"backtest_result", "mathematician", {
  run: string;
  train: Stats;
  validation: Stats;
  baseline: BaselineStats;
  equity_train: EquityPoint[];
  equity_validation: EquityPoint[];
  histogram: unknown;
}>;
export type CheckResultEvent = Base<"check_result", "naysayer", { check: string; passed: boolean; value: unknown; note: string }>;
export type FollowupRequestedEvent = Base<"followup_requested", "naysayer", { followup: string; reason: string }>;
export type RecoveredEvent = Base<"recovered", Agent | null, { failed: string; action: string; injected: boolean }>;
export type VerdictEvent = Base<"verdict", null, {
  verdict: Verdict;
  reason: string;
  headline: { n?: number; mean?: number; ci_low?: number; paired_ci_low?: number };
  downgrades: { cause?: string; [k: string]: unknown }[];
}>;
export type ReportReadyEvent = Base<"report_ready", "reporter", { path: string; trace_id: string | null; prose_included: boolean }>;
export type ErrorEvent = Base<"error", Agent | null, { step: string; message: string }>;

export type AuditEvent =
  | AuditStartedEvent
  | AgentStartedEvent
  | AgentFinishedEvent
  | LlmCallEvent
  | ToolCalledEvent
  | ToolResultEvent
  | DataProgressEvent
  | BacktestResultEvent
  | CheckResultEvent
  | FollowupRequestedEvent
  | RecoveredEvent
  | VerdictEvent
  | ReportReadyEvent
  | ErrorEvent;

export interface AuditSummary {
  audit_id: string;
  idea: string;
  started_at: string;
  finished: boolean;
}
// Pure reducer: folds audit events into screen state. Every panel renders only this state.
// The UI computes nothing itself except the running totals of llm_call events (section 16).
import type { Agent, AuditEvent, BaselineStats, EquityPoint, Stats, VerdictEvent } from "./events";

export type AgentStatus = "idle" | "active" | "done" | "error";
export const agentOrder: Agent[] = ["planner", "researcher", "mathematician", "naysayer", "reporter"];

export interface UiState {
  phase: "idle" | "running" | "done";
  idea: string;
  provider: string | null;
  startedAt: string | null;
  traceId: string | null;
  whatTested: string | null;
  planHash: string | null;
  agents: Record<Agent, AgentStatus>;
  lastAgent: Agent | null;
  links: { from: Agent; to: Agent; key: number } | null;
  equityTrain: EquityPoint[];
  equityValidation: EquityPoint[];
  equityRun: string | null;
  stats: { train: Stats; validation: Stats; baseline: BaselineStats } | null;
  followups: { id: string; reason: string }[];
  followupsRun: number;
  checks: { check: string; passed: boolean; value: unknown; note: string }[];
  recoveries: { failed: string; action: string; injected: boolean }[];
  verdict: VerdictEvent["payload"] | null;
  report: { path: string; traceId: string | null } | null;
  meters: { llmCalls: number; budget: number; promptTokens: number; completionTokens: number; costUsd: number };
  lastSeq: number;
  lastTs: string | null;
  errors: string[];
}

export const initialState: UiState = {
  phase: "idle",
  idea: "",
  provider: null,
  startedAt: null,
  traceId: null,
  whatTested: null,
  planHash: null,
  agents: { planner: "idle", researcher: "idle", mathematician: "idle", naysayer: "idle", reporter: "idle", triage: "idle" },
  lastAgent: null,
  links: null,
  equityTrain: [],
  equityValidation: [],
  equityRun: null,
  stats: null,
  followups: [],
  followupsRun: 0,
  checks: [],
  recoveries: [],
  verdict: null,
  report: null,
  meters: { llmCalls: 0, budget: 8, promptTokens: 0, completionTokens: 0, costUsd: 0 },
  lastSeq: 0,
  lastTs: null,
  errors: [],
};

let linkKey = 0;
const link = (from: Agent, to: Agent) => ({ from, to, key: ++linkKey });

function summaryField(summary: unknown, field: string): string | null {
  if (summary && typeof summary === "object" && field in summary) {
    const v = (summary as Record<string, unknown>)[field];
    return typeof v === "string" ? v : null;
  }
  return null;
}

export function reduce(prev: UiState, e: AuditEvent): UiState {
  const s: UiState = { ...prev, lastSeq: e.seq, lastTs: e.ts };
  switch (e.type) {
    case "audit_started":
      return { ...s, phase: "running", idea: e.payload.idea, provider: e.payload.provider ?? null, startedAt: e.ts, traceId: e.payload.trace_id,
        meters: { ...s.meters, budget: e.payload.llm_budget } };
    case "agent_started":
      return { ...s, phase: s.phase === "idle" ? "running" : s.phase,
        agents: { ...s.agents, [e.agent]: "active" },
        links: s.lastAgent && s.lastAgent !== e.agent ? link(s.lastAgent, e.agent) : s.links,
        lastAgent: e.agent };
    case "agent_finished":
      return { ...s, agents: { ...s.agents, [e.agent]: e.payload.status === "error" ? "error" : "done" },
        whatTested: summaryField(e.payload.summary, "what_tested") ?? s.whatTested,
        planHash: summaryField(e.payload.summary, "plan_hash") ?? s.planHash };
    case "llm_call": {
      const m = s.meters;
      return { ...s, meters: { ...m, llmCalls: m.llmCalls + 1, promptTokens: m.promptTokens + e.payload.prompt_tokens,
        completionTokens: m.completionTokens + e.payload.completion_tokens, costUsd: m.costUsd + e.payload.cost_usd } };
    }
    case "backtest_result": {
      const isFollowup = /^F\d/.test(e.payload.run);
      const next = { ...s, followupsRun: s.followupsRun + (isFollowup ? 1 : 0) };
      if (e.payload.run !== "base") return next;
      return { ...next, equityTrain: e.payload.equity_train, equityValidation: e.payload.equity_validation,
        equityRun: e.payload.run, stats: { train: e.payload.train, validation: e.payload.validation, baseline: e.payload.baseline } };
    }
    case "check_result":
      return { ...s, checks: [...s.checks, e.payload] };
    case "followup_requested":
      return { ...s, followups: [...s.followups, { id: e.payload.followup, reason: e.payload.reason }],
        links: link("naysayer", "mathematician") };
    case "recovered":
      return { ...s, recoveries: [...s.recoveries, e.payload] };
    case "verdict": {
      // Tolerate a payload with missing parts so one odd line never blanks the screen.
      const p = e.payload ?? ({} as VerdictEvent["payload"]);
      const headline = p.headline && typeof p.headline === "object" ? p.headline : {};
      const downgrades = Array.isArray(p.downgrades) ? p.downgrades : [];
      return { ...s, phase: "done", verdict: { ...p, verdict: p.verdict, reason: typeof p.reason === "string" ? p.reason : "", headline, downgrades } };
    }
    case "report_ready":
      return { ...s, report: { path: e.payload.path, traceId: e.payload.trace_id }, agents: { ...s.agents, reporter: "done" } };
    case "error":
      return { ...s, phase: "done", errors: [...s.errors, `${e.payload.step}: ${e.payload.message}`],
        agents: e.agent ? { ...s.agents, [e.agent]: "error" } : s.agents };
    default:
      return s;
  }
}
import { useReducedMotion } from "framer-motion";
import { AgentGraph } from "./components/AgentGraph";
import { CommandBar } from "./components/CommandBar";
import { EquityCurves } from "./components/EquityCurves";
import { FooterMeters } from "./components/FooterMeters";
import { Panel } from "./components/Panel";
import { ReplayControls } from "./components/ReplayControls";
import { VerdictStamp } from "./components/VerdictStamp";
import { useAudit } from "./useAudit";

// Demo ideas, exact text from AUDITOR_SPEC.md section 13.
export const DEMO_IDEAS = ["buy dips in an uptrend", "buy straddles on tech before earnings", "sell straddles on low-volatility mega-caps"];

export default function App() {
  const a = useAudit();
  const reduced = useReducedMotion() ?? false;
  const state = a.state;
  const canResume = !!a.currentAuditId && state.phase !== "done";
  const elapsedMs = state.startedAt && state.lastTs ? Date.parse(state.lastTs) - Date.parse(state.startedAt) : 0;
  const reportUrl = a.currentAuditId && state.report ? `/api/audits/${encodeURIComponent(a.currentAuditId)}/report` : null;

  return (
    <div className="grid h-full grid-rows-[auto_minmax(0,1fr)_auto_auto] gap-3 p-4">
      <CommandBar
        state={a.state}
        mode={a.mode}
        chips={DEMO_IDEAS}
        onSubmit={a.submitIdea}
        controls={
          <ReplayControls
            playing={a.playing}
            speed={a.speed}
            onPlay={a.resume}
            onPause={a.pause}
            onSpeed={a.setSpeed}
            disabled={!a.playing && !canResume}
          />
        }
      />
      <div className="grid min-h-0 grid-cols-[5fr_7fr] gap-3">
        <Panel title="Agents" right={state.lastAgent && <span className="font-mono text-[11px] text-muted">{state.lastAgent}</span>}>
          <AgentGraph state={state} reduced={reduced} />
        </Panel>
        <Panel title="Evidence" right={state.equityRun && <span className="font-mono text-[11px] text-muted">run: {state.equityRun}</span>}>
          <EquityCurves state={state} reduced={reduced} />
        </Panel>
      </div>
      <div className="h-40">
        <VerdictStamp state={state} reduced={reduced} reportUrl={reportUrl} traceUrl={null} />
      </div>
      <FooterMeters state={state} elapsedMs={Number.isFinite(elapsedMs) ? elapsedMs : 0} followupsRun={state.followupsRun} />
      {a.state.errors.length > 0 && (
        <div role="alert" className="fixed right-4 bottom-16 max-w-md rounded border border-kill/60 bg-panel px-4 py-3 text-sm text-text shadow-lg">
          {a.state.errors[a.state.errors.length - 1]}
        </div>
      )}
    </div>
  );
}
@import "tailwindcss";

@theme {
  --font-sans: "IBM Plex Sans", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --color-bg: #0b0e13;
  --color-panel: #11161e;
  --color-line: #1f2733;
  --color-text: #e6edf3;
  --color-muted: #8b98a8;
  --color-accent: #4cc9f0;
  --color-kill: #ef4444;
  --color-inconclusive: #f59e0b;
  --color-promising: #22c55e;
  --color-cannot: #6b7280;
}

html, body, #root { height: 100%; }
body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
import type { ReactNode } from "react";

export function Panel({ title, right, children, className = "" }: { title: string; right?: ReactNode; children: ReactNode; className?: string }) {
  return (
    <section className={`flex min-h-0 flex-col rounded-md border border-line bg-panel ${className}`}>
      <header className="flex items-center justify-between border-b border-line px-4 py-2">
        <h2 className="font-mono text-[11px] font-semibold uppercase tracking-[0.18em] text-muted">{title}</h2>
        {right}
      </header>
      <div className="min-h-0 flex-1 p-4">{children}</div>
    </section>
  );
}
// Number formatting for the mono figures. Returns are fractions (0.012 = 1.2%).
export const pct = (x: number | undefined | null, digits = 2): string =>
  typeof x === "number" && Number.isFinite(x) ? `${x > 0 ? "+" : ""}${(x * 100).toFixed(digits)}%` : "–";
export const int = (n: number | undefined | null): string =>
  typeof n === "number" && Number.isFinite(n) ? Math.round(n).toLocaleString("en-US") : "–";
export const usd = (x: number): string => `$${x.toFixed(4)}`;

// Agent graph: the section 4 loop as five nodes. Every animation marks an event:
// a node lights on agent_started, settles on agent_finished, a dot travels a link when work moves
// (links.key changes), and the return arc animates on each followup_requested.
import { motion } from "framer-motion";
import type { Agent } from "../events";
import { agentOrder, type AgentStatus, type UiState } from "../state";

const W = 760, H = 420, NODE_W = 124, NODE_H = 64, Y = 190;
const X: Record<Agent, number> = { planner: 78, researcher: 229, mathematician: 380, naysayer: 531, reporter: 682, triage: 78 };
const LABEL: Record<Agent, string> = { planner: "Planner", researcher: "Researcher", mathematician: "Mathematician", naysayer: "Naysayer", reporter: "Reporter", triage: "Triage" };
const STROKE: Record<AgentStatus, string> = { idle: "var(--color-line)", active: "var(--color-accent)", done: "var(--color-promising)", error: "var(--color-kill)" };
const RETURN_ARC = `M ${X.naysayer} ${Y + NODE_H / 2} C ${X.naysayer} ${Y + 150}, ${X.mathematician} ${Y + 150}, ${X.mathematician} ${Y + NODE_H / 2}`;

function linkPath(from: Agent, to: Agent): string {
  if (from === "naysayer" && to === "mathematician") return RETURN_ARC;
  const [a, b] = X[from] < X[to] ? [X[from] + NODE_W / 2, X[to] - NODE_W / 2] : [X[from] - NODE_W / 2, X[to] + NODE_W / 2];
  return `M ${a} ${Y} L ${b} ${Y}`;
}

export function AgentGraph({ state, reduced }: { state: UiState; reduced: boolean }) {
  const followups = state.followups.length;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="h-full w-full" role="img" aria-label="Agent pipeline">
      {/* forward chain */}
      {agentOrder.slice(0, -1).map((from, i) => {
        const to = agentOrder[i + 1];
        return <path key={from} d={linkPath(from, to)} stroke="var(--color-line)" strokeWidth={2} fill="none" />;
      })}
      {/* return arc: naysayer asks the mathematician for follow-ups */}
      <path d={RETURN_ARC} stroke={followups ? "var(--color-accent)" : "var(--color-line)"} strokeWidth={2} fill="none" strokeDasharray="6 6" opacity={followups ? 0.9 : 0.5} />
      <text x={(X.naysayer + X.mathematician) / 2} y={Y + 128} textAnchor="middle" className="font-mono" fontSize={11} fill={followups ? "var(--color-accent)" : "var(--color-muted)"}>
        follow-ups ×{followups}
      </text>

      {/* travelling dot, remounted on every handoff */}
      {!reduced && state.links && (
        <circle key={state.links.key} r={5} fill="var(--color-accent)">
          <animateMotion dur="0.5s" path={linkPath(state.links.from, state.links.to)} fill="freeze" calcMode="spline" keySplines="0.16 1 0.3 1" keyTimes="0;1" />
        </circle>
      )}

      {agentOrder.map((agent) => {
        const status = state.agents[agent];
        const active = status === "active";
        const x = X[agent] - NODE_W / 2, y = Y - NODE_H / 2;
        return (
          <g key={agent}>
            <motion.rect
              x={x} y={y} width={NODE_W} height={NODE_H} rx={6}
              fill="var(--color-bg)"
              stroke={STROKE[status]}
              strokeWidth={active ? 2 : 1.5}
              style={{ transformBox: "fill-box", transformOrigin: "center", filter: active && !reduced ? "drop-shadow(0 0 10px var(--color-accent))" : "none" }}
              animate={{ scale: active && !reduced ? 1.05 : 1 }}
              transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            />
            <text x={X[agent]} y={Y - 4} textAnchor="middle" fontSize={15} fontWeight={600} fill={status === "idle" ? "var(--color-muted)" : "var(--color-text)"}>
              {LABEL[agent]}
            </text>
            <text x={X[agent]} y={Y + 18} textAnchor="middle" className="font-mono" fontSize={10} letterSpacing={1.5} fill={STROKE[status === "idle" ? "idle" : status]} style={{ textTransform: "uppercase" }}>
              {status === "idle" ? "standby" : status}
            </text>
            {agent === "researcher" && state.recoveries.map((r, i) => (
              <g key={i}>
                <rect x={X.researcher - 66} y={y - 30 - i * 22} width={132} height={18} rx={9} fill="var(--color-panel)" stroke={r.injected ? "var(--color-inconclusive)" : "var(--color-kill)"} />
                <text x={X.researcher} y={y - 17 - i * 22} textAnchor="middle" className="font-mono" fontSize={10} letterSpacing={1} fill={r.injected ? "var(--color-inconclusive)" : "var(--color-kill)"}>
                  <title>{`${r.failed}: ${r.action}`}</title>
                  {r.injected ? "RECOVERED · INJECTED" : "RECOVERED · REAL"}
                </text>
              </g>
            ))}
          </g>
        );
      })}
    </svg>
  );
}
// Verdict stamp: lands on the verdict event (the one long animation, 900 ms), headline figures count
// up from zero. Copy for the subtitles is fixed by AUDITOR_SPEC.md sections 1 and 9.
import { motion } from "framer-motion";
import { useEffect, useRef } from "react";
import type { Verdict } from "../events";
import { int, pct } from "../fmt";
import type { UiState } from "../state";
import { runLabel } from "../useAudit";
import { countUp } from "./countUp";

const STAMP: Record<Verdict, { label: string; color: string }> = {
  kill: { label: "KILLED", color: "var(--color-kill)" },
  inconclusive: { label: "INCONCLUSIVE", color: "var(--color-inconclusive)" },
  promising: { label: "PROMISING", color: "var(--color-promising)" },
  cannot_audit: { label: "CANNOT AUDIT", color: "var(--color-cannot)" },
};
const SUBTITLE: Partial<Record<Verdict, string>> = {
  promising: "Passed a 6-month historical screen. Not a forecast. Not financial advice.",
  inconclusive: "inconclusive: a strategy with no real edge lands here about half the time",
};
const REVEAL_MS = 900;

function Figure({ label, value, format, reduced }: { label: string; value: number | undefined; format: (v: number) => string; reduced: boolean }) {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof value !== "number") return;
    return countUp(0, value, reduced ? 0 : REVEAL_MS, (v) => {
      el.textContent = format(v);
    });
  }, [value, format, reduced]);
  return (
    <div className="flex flex-col">
      <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">{label}</span>
      <span ref={ref} className="font-mono text-2xl font-semibold tabular-nums text-text">{typeof value === "number" ? format(0) : "–"}</span>
    </div>
  );
}

export function VerdictStamp({ state, reduced, reportUrl, traceUrl }: { state: UiState; reduced: boolean; reportUrl: string | null; traceUrl: string | null }) {
  const v = state.verdict;
  if (!v) {
    return (
      <div className="flex h-full items-center justify-center rounded-md border border-dashed border-line font-mono text-xs tracking-[0.2em] text-muted">
