    s = reduce(s, ev(2, { type: "check_result", agent: "naysayer", payload: { check: "evidence", passed: true, value: 1, note: "n" } }));
    s = reduce(s, ev(3, { type: "error", agent: null, payload: { step: "run", message: "boom" } }));
